#!/usr/bin/env python3
"""
GENERADOR HTML V3 - Versión actualizada y sincronizada:
- Carga questions_data.json desde la carpeta actual (MANDATORIOS)
- Conserva temas (tp), fuentes (src) y las 554 preguntas auditadas doctrinalmente
- Incluye pantalla de inicio, Simulacro de Prueba Final (36 preguntas), filtros por eje temático,
  buscador de Banco de Preguntas y exportación a PDF / Word (con y sin respuestas)
- Actualiza automáticamente tanto index.html como test_mediacion_policial.html
"""
import json
import os
from collections import Counter

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
JSON_PATH = os.path.join(BASE_DIR, 'questions_data.json')

with open(JSON_PATH, 'r', encoding='utf-8') as f:
    all_q = json.load(f)

questions = []
for q in all_q:
    opts = [o for o in q.get('options', []) if o and o != '(Ver enunciado)']
    if len(opts) >= 2:
        c_idx = min(max(0, q.get('correct', 0)), len(opts) - 1)
        questions.append({
            'q': q['question'],
            'opts': opts[:4],
            'src': q.get('source', ''),
            'tp': q.get('topic', 'Procedimientos Policiales'),
            'c': c_idx
        })

total = len(questions)
print(f"Preguntas válidas cargadas: {total}")

js_lines = [
    "  " + json.dumps(q, ensure_ascii=False, separators=(',', ':'))
    for q in questions
]
js_data = "const QS=[\n" + ",\n".join(js_lines) + "\n];"

HTML_PREFIX = '<!DOCTYPE html>\n<html lang="es">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">\n<title>Evaluacion Integral Policial | 554 Preguntas</title>\n<link href="https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@500;600;700;800&family=Source+Sans+3:wght@400;500;600;700&display=swap" rel="stylesheet">\n<style>\n:root{\n  --navy:#0a1628;--navy-mid:#132340;--navy-light:#1c3258;\n  --gold:#c9a84c;--gold-b:#e4c35a;--gold-d:#8a7234;\n  --ng:#39ff14;--ng2:#00e676;\n  --green:#27ae60;--gd:#1e8449;\n  --nr:#ff1744;--nr2:#ff5252;\n  --red:#c0392b;--rd:#922b21;\n  --w:#fff;--g50:#f8f9fa;--g100:#eef0f2;\n  --g200:#dde1e6;--g300:#bcc3cc;--g500:#6c757d;\n  --g700:#3d4654;--g900:#1a1e26;\n  --r:8px;\n  --safe-bottom: env(safe-area-inset-bottom, 0px);\n}\n*{margin:0;padding:0;box-sizing:border-box;-webkit-tap-highlight-color:transparent;}\nhtml{height:100%;}\nbody{font-family:\'Source Sans 3\',\'Segoe UI\',sans-serif;background:var(--g100);\n  color:var(--g900);display:flex;flex-direction:column;height:100%;\n  overflow:hidden;}\n\n/* ── HEADER ── */\n.hdr{background:linear-gradient(135deg,var(--navy),var(--navy-mid) 60%,var(--navy-light));\n  color:#fff;display:flex;align-items:center;justify-content:space-between;\n  padding:0 16px;height:52px;flex-shrink:0;\n  box-shadow:0 3px 12px rgba(0,0,0,.35);position:relative;z-index:20;}\n.hdr::after{content:\'\';position:absolute;bottom:0;left:0;right:0;height:3px;\n  background:linear-gradient(90deg,var(--gold),var(--gold-b),var(--gold));}\n.hbrand{display:flex;align-items:center;gap:10px;min-width:0;}\n.htitle{font-family:\'Barlow Condensed\',sans-serif;font-size:18px;font-weight:700;\n  letter-spacing:1.5px;text-transform:uppercase;white-space:nowrap;}\n.hsub{font-size:10px;opacity:.65;letter-spacing:.8px;text-transform:uppercase;\n  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:220px;}\n.hctrl{display:flex;gap:4px;align-items:center;flex-shrink:0;}\n.hbtn{background:rgba(255,255,255,.1);border:1px solid rgba(201,168,76,.4);\n  color:var(--gold-b);padding:5px 10px;border-radius:6px;cursor:pointer;\n  font-size:11px;font-weight:600;letter-spacing:.3px;transition:all .2s;\n  text-transform:uppercase;white-space:nowrap;}\n.hbtn:hover{background:rgba(201,168,76,.2);}\n.hmenu{font-size:22px;cursor:pointer;padding:4px 6px;color:var(--gold-b);\n  user-select:none;line-height:1;}\n\n/* ── STATS BAR ── */\n.stats{background:#fff;border-bottom:1px solid var(--g200);\n  display:flex;justify-content:center;gap:0;flex-shrink:0;}\n.stat{text-align:center;padding:8px 16px;border-right:1px solid var(--g100);flex:1;\n  max-width:120px;}\n.stat:last-child{border-right:none;}\n.sv{font-family:\'Barlow Condensed\',sans-serif;font-size:20px;font-weight:700;line-height:1;}\n.sv.vq{color:var(--navy);} .sv.vok{color:var(--green);}\n.sv.vfail{color:var(--red);} .sv.vpts{color:var(--gold-d);}\n.sl{font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:1px;\n  color:var(--g500);margin-top:1px;}\n\n/* ── MAIN CONTAINER ── */\n.main{flex:1;display:flex;overflow:hidden;position:relative;}\n\n/* ── HOME SCREEN ── */\n.homescreen{flex:1;overflow-y:auto;padding:20px 16px 32px;background:var(--g100);\n  display:flex;flex-direction:column;align-items:center;gap:20px;}\n.homescreen.hidden{display:none;}\n.home-title{font-family:\'Barlow Condensed\',sans-serif;font-size:24px;font-weight:800;\n  color:var(--navy);text-align:center;letter-spacing:1px;text-transform:uppercase;}\n.home-sub{font-size:13px;color:var(--g500);text-align:center;line-height:1.5;}\n.home-cards{display:grid;grid-template-columns:1fr 1fr;gap:12px;width:100%;max-width:800px;}\n.home-card{background:#fff;border-radius:12px;padding:20px 14px;cursor:pointer;\n  transition:all .2s;border:2px solid var(--g200);text-align:center;\n  box-shadow:0 2px 8px rgba(0,0,0,.07);active-color:var(--navy);}\n.home-card:active{transform:scale(.97);}\n.home-card:hover{transform:translateY(-3px);box-shadow:0 6px 20px rgba(0,0,0,.12);border-color:var(--gold);}\n.home-card.featured{border-color:var(--gold);background:linear-gradient(135deg,#fffdf0,#fff9e6);}\n.hcard-icon{font-size:36px;margin-bottom:8px;}\n.hcard-title{font-family:\'Barlow Condensed\',sans-serif;font-size:17px;font-weight:800;\n  color:var(--navy);text-transform:uppercase;letter-spacing:.8px;margin-bottom:5px;}\n.hcard-desc{font-size:11px;color:var(--g500);line-height:1.4;margin-bottom:10px;}\n.hcard-badge{display:inline-block;padding:3px 10px;border-radius:16px;font-size:11px;\n  font-weight:700;background:var(--navy);color:var(--gold-b);}\n\n/* TOPIC GRID 2x2 */\n.topic-grid{display:grid;grid-template-columns:1fr 1fr;gap:10px;width:100%;max-width:800px;}\n.tbtn{background:#fff;border:2px solid;border-radius:10px;padding:14px 12px;cursor:pointer;\n  transition:all .2s;display:flex;align-items:center;gap:10px;text-align:left;\n  box-shadow:0 2px 6px rgba(0,0,0,.06);}\n.tbtn:active{transform:scale(.97);}\n.tbtn-icon{font-size:24px;flex-shrink:0;}\n.tbtn-name{font-family:\'Barlow Condensed\',sans-serif;font-size:14px;font-weight:700;\n  text-transform:uppercase;letter-spacing:.4px;flex:1;line-height:1.2;}\n.tbtn-count{font-size:10px;color:var(--g500);font-weight:600;white-space:nowrap;}\n\n/* BANCO button on home */\n.banco-btn{width:100%;max-width:800px;background:#fff;border:2px solid var(--navy);\n  border-radius:10px;padding:14px 20px;cursor:pointer;display:flex;align-items:center;\n  gap:12px;transition:all .2s;box-shadow:0 2px 6px rgba(0,0,0,.07);}\n.banco-btn:active{transform:scale(.98);}\n.banco-btn-text{font-family:\'Barlow Condensed\',sans-serif;font-size:16px;font-weight:700;\n  color:var(--navy);text-transform:uppercase;letter-spacing:.5px;}\n.banco-btn-sub{font-size:12px;color:var(--g500);}\n\n/* ── QUESTION WRAPPER ── */\n.qwrap{flex:1;display:flex;flex-direction:column;overflow:hidden;}\n.qwrap.hidden{display:none;}\n.qmode-bar{background:var(--navy-mid);color:var(--gold-b);padding:8px 16px;\n  font-family:\'Barlow Condensed\',sans-serif;font-size:12px;font-weight:700;\n  letter-spacing:.8px;text-transform:uppercase;display:flex;justify-content:space-between;\n  align-items:center;flex-shrink:0;}\n.progbar{padding:5px 16px;background:var(--g50);border-bottom:1px solid var(--g200);\n  flex-shrink:0;}\n.progbar-inner{height:6px;background:var(--g200);border-radius:3px;overflow:hidden;}\n.progbar-fill{height:100%;background:linear-gradient(90deg,var(--ng2),var(--ng));\n  border-radius:3px;transition:width .4s;}\n.prog-lbl{font-size:10px;color:var(--g500);font-weight:600;margin-bottom:3px;text-align:right;}\n.qpanel{flex:1;overflow-y:auto;padding:12px;-webkit-overflow-scrolling:touch;}\n.qcard{background:#fff;border:1px solid var(--g200);border-radius:10px;\n  display:flex;flex-direction:column;box-shadow:0 3px 10px rgba(0,0,0,.1);\n  overflow:hidden;position:relative;}\n.qsrc{padding:5px 14px;background:var(--g50);border-bottom:1px solid var(--g200);\n  font-size:10px;font-weight:700;color:var(--g500);text-transform:uppercase;\n  letter-spacing:.8px;display:flex;align-items:center;gap:8px;flex-wrap:wrap;}\n.qtbadge{padding:2px 8px;border-radius:8px;font-size:9px;font-weight:700;\n  text-transform:uppercase;color:#fff;white-space:nowrap;}\n.qtext{padding:16px 16px 12px;font-size:15px;line-height:1.65;color:var(--g900);\n  border-bottom:2px solid var(--gold);}\n.qopts{padding:12px 12px 16px;}\n\n/* OPTIONS - big tap targets for mobile */\n.opt{display:flex;align-items:flex-start;gap:10px;padding:14px 14px;margin-bottom:8px;\n  cursor:pointer;border-radius:10px;transition:all .18s;\n  border:2px solid var(--g200);background:#fff;\n  min-height:52px;-webkit-tap-highlight-color:transparent;}\n.opt:active:not(.answered){transform:scale(.98);background:#f0f4ff;}\n.opt:hover:not(.answered){background:#f0f4ff;border-color:var(--navy-light);}\n.opt.correct{background:#e1ffe1;border-color:var(--ng2);\n  box-shadow:0 0 16px rgba(57,255,20,.3);cursor:default;}\n.opt.incorrect{background:#ffe1e1;border-color:var(--nr2);\n  box-shadow:0 0 16px rgba(255,23,68,.3);cursor:default;}\n.opt.wascorrect{background:#e1ffe1;border-color:var(--ng2);opacity:.8;cursor:default;}\n.opt.answered{cursor:default;}\n.ocirc{width:26px;height:26px;border:2px solid var(--g300);border-radius:50%;\n  flex-shrink:0;margin-top:1px;display:flex;align-items:center;justify-content:center;\n  font-size:14px;font-weight:700;color:#fff;transition:all .18s;}\n.opt.correct .ocirc{background:var(--ng2);border-color:var(--ng2);}\n.opt.correct .ocirc::after{content:\'\\2713\';}\n.opt.incorrect .ocirc{background:var(--nr2);border-color:var(--nr2);}\n.opt.incorrect .ocirc::after{content:\'\\2717\';}\n.opt.wascorrect .ocirc{background:var(--ng2);border-color:var(--ng2);}\n.opt.wascorrect .ocirc::after{content:\'\\2713\';}\n.otxt{font-size:14px;line-height:1.45;color:var(--g700);flex:1;}\n.opt.correct .otxt{color:var(--gd);font-weight:700;}\n.opt.incorrect .otxt{color:var(--rd);font-weight:600;text-decoration:line-through;}\n.opt.wascorrect .otxt{color:var(--gd);font-weight:600;}\n\n/* RESULT OVERLAY */\n.roverlay{display:none;position:absolute;inset:0;z-index:5;\n  justify-content:center;align-items:center;flex-direction:column;\n  animation:rpop .35s ease;}\n.roverlay.show{display:flex;}\n.roverlay.rcorrect{background:radial-gradient(circle,rgba(57,255,20,.22) 0%,rgba(0,230,118,.12) 70%,transparent);}\n.roverlay.rincorrect{background:radial-gradient(circle,rgba(255,23,68,.2) 0%,rgba(255,82,82,.1) 70%,transparent);}\n@keyframes rpop{0%{opacity:0;transform:scale(.4)} 60%{transform:scale(1.07)} 100%{opacity:1;transform:scale(1)}}\n.rico{font-size:80px;margin-bottom:6px;animation:bounce .5s ease;}\n@keyframes bounce{0%{transform:translateY(-25px);opacity:0} 55%{transform:translateY(8px)} 75%{transform:translateY(-5px)} 100%{transform:translateY(0);opacity:1}}\n.rtxt{font-family:\'Barlow Condensed\',sans-serif;font-size:42px;font-weight:800;\n  letter-spacing:4px;text-transform:uppercase;animation:glow 1.5s ease infinite alternate;}\n.rtxt.rg{color:var(--ng);}\n.rtxt.rr{color:var(--nr);}\n@keyframes glow{from{text-shadow:0 0 10px currentColor,0 0 20px currentColor}\n  to{text-shadow:0 0 25px currentColor,0 0 50px currentColor,0 0 80px currentColor}}\n.rsub{font-family:\'Barlow Condensed\',sans-serif;font-size:15px;font-weight:600;\n  color:var(--g500);margin-top:6px;letter-spacing:1px;}\n.cbox{position:absolute;inset:0;overflow:hidden;pointer-events:none;z-index:6;}\n.conf{position:absolute;width:9px;height:9px;top:-10px;animation:cfall 2s ease-in forwards;}\n@keyframes cfall{0%{transform:translateY(0) rotate(0deg);opacity:1}\n  100%{transform:translateY(110vh) rotate(720deg);opacity:0}}\n\n/* ── BOTTOM NAV (mobile friendly) ── */\n.bottom{background:#fff;padding:10px 12px;padding-bottom:calc(10px + var(--safe-bottom));\n  display:flex;justify-content:center;align-items:center;gap:8px;\n  border-top:2px solid var(--g200);flex-shrink:0;\n  box-shadow:0 -3px 12px rgba(0,0,0,.08);}\n.btn{font-family:\'Barlow Condensed\',sans-serif;font-size:15px;font-weight:700;\n  letter-spacing:.5px;text-transform:uppercase;border:2px solid var(--g200);\n  border-radius:8px;cursor:pointer;transition:all .18s;background:#fff;\n  color:var(--g700);padding:11px 16px;min-height:46px;display:flex;\n  align-items:center;justify-content:center;gap:5px;}\n.btn:active{transform:scale(.96);}\n.btnnav{padding:11px 18px;font-size:18px;color:var(--navy);flex-shrink:0;}\n.btnhome{background:var(--g50);border-color:var(--g300);color:var(--g700);\n  padding:11px 14px;flex-shrink:0;}\n.btnres{background:var(--navy);color:var(--gold-b);border-color:var(--navy);flex:1;max-width:180px;}\n\n/* ── SIDEBAR ── */\n.sidebar{width:190px;background:#fff;border-left:3px solid var(--navy);\n  display:flex;flex-direction:column;flex-shrink:0;\n  transition:margin-right .28s cubic-bezier(.4,0,.2,1);z-index:10;\n  box-shadow:-4px 0 16px rgba(0,0,0,.1);}\n.sidebar.collapsed{margin-right:-190px;}\n.sbhead{background:var(--navy);color:var(--gold-b);padding:10px 12px;\n  font-family:\'Barlow Condensed\',sans-serif;font-size:13px;font-weight:700;\n  letter-spacing:1.2px;text-transform:uppercase;\n  display:flex;justify-content:space-between;align-items:center;flex-shrink:0;}\n.sbbody{flex:1;overflow-y:auto;-webkit-overflow-scrolling:touch;}\n.sbi{padding:9px 12px;font-size:12px;cursor:pointer;\n  border-bottom:1px solid var(--g100);transition:all .15s;\n  display:flex;justify-content:space-between;align-items:center;color:var(--g700);}\n.sbi:active{background:var(--g50);}\n.sbi.active{background:#e8eef8;color:var(--navy);font-weight:700;border-left:3px solid var(--gold);}\n.sbi.ok{background:#d4ffd4;color:#0a6b2e;}\n.sbi.fail{background:#ffd4d4;color:#8b1a1a;}\n.sbico{font-size:12px;font-weight:700;}\n.toggle{position:absolute;right:190px;top:50%;transform:translateY(-50%);\n  width:22px;height:48px;background:var(--navy);color:var(--gold-b);\n  display:flex;align-items:center;justify-content:center;\n  cursor:pointer;border-radius:8px 0 0 8px;font-size:12px;z-index:11;\n  transition:right .28s cubic-bezier(.4,0,.2,1);}\n.toggle.collapsed{right:0;}\n\n/* ── DESCARGA BUTTONS ── */\n.dl-row{display:flex;gap:8px;flex-wrap:wrap;padding:4px 0;}\n.dl-btn{flex:1;min-width:140px;display:flex;align-items:center;justify-content:center;gap:7px;\n  padding:10px 10px;border-radius:10px;font-family:\'Barlow Condensed\',sans-serif;\n  font-size:13px;font-weight:700;cursor:pointer;border:none;text-transform:uppercase;\n  letter-spacing:.5px;transition:all .2s;box-shadow:0 2px 6px rgba(0,0,0,.12);}\n.dl-btn:active{transform:scale(.96);}\n.dl-btn-pdf{background:#c62828;color:#fff;}\n.dl-btn-word{background:#1565c0;color:#fff;}\n.dl-btn-exam{background:#e65100;color:#fff;}\n.dl-btn .dl-ico{font-size:17px;}\n.dl-btn .dl-lbl{display:flex;flex-direction:column;line-height:1.1;text-align:left;}\n.dl-btn .dl-lbl small{font-size:9px;font-weight:400;opacity:.85;text-transform:none;letter-spacing:0;}\n\n/* ── BANCO DE PREGUNTAS ── */\n.banco{flex:1;display:flex;flex-direction:column;overflow:hidden;}\n.banco.hidden{display:none;}\n.banco-top{background:#fff;padding:12px 16px;border-bottom:2px solid var(--g200);\n  flex-shrink:0;display:flex;flex-direction:column;gap:10px;}\n.banco-title{font-family:\'Barlow Condensed\',sans-serif;font-size:18px;font-weight:800;\n  color:var(--navy);text-transform:uppercase;letter-spacing:1px;}\n.banco-search{display:flex;gap:8px;}\n.search-inp{flex:1;padding:10px 14px;border:2px solid var(--g200);border-radius:8px;\n  font-size:14px;font-family:\'Source Sans 3\',sans-serif;outline:none;\n  transition:border-color .2s;}\n.search-inp:focus{border-color:var(--navy);}\n.banco-filters{display:flex;gap:6px;overflow-x:auto;padding-bottom:2px;}\n.bfilter{padding:5px 12px;border-radius:16px;font-size:11px;font-weight:700;\n  border:2px solid var(--g200);background:#fff;cursor:pointer;white-space:nowrap;\n  transition:all .2s;text-transform:uppercase;letter-spacing:.4px;}\n.bfilter.active{color:#fff;border-color:transparent;}\n.banco-list{flex:1;overflow-y:auto;padding:12px;-webkit-overflow-scrolling:touch;}\n.bq{background:#fff;border-radius:10px;padding:14px;margin-bottom:10px;\n  border-left:4px solid var(--g300);box-shadow:0 1px 4px rgba(0,0,0,.07);}\n.bq-num{font-size:10px;font-weight:700;color:var(--g500);text-transform:uppercase;\n  letter-spacing:.8px;margin-bottom:4px;}\n.bq-topic{display:inline-block;padding:2px 8px;border-radius:6px;font-size:9px;\n  font-weight:700;color:#fff;text-transform:uppercase;margin-left:6px;}\n.bq-text{font-size:13.5px;color:var(--g900);line-height:1.5;margin-bottom:8px;font-weight:500;}\n.bq-answer{font-size:12.5px;line-height:1.4;padding:8px 12px;border-radius:6px;\n  display:flex;align-items:flex-start;gap:7px;}\n.bq-answer.correct{background:#e1ffe1;color:var(--gd);}\n.bq-chk{font-weight:700;font-size:14px;flex-shrink:0;margin-top:1px;}\n.bq-opts{margin-top:6px;}\n.bq-opt{font-size:12px;color:var(--g700);padding:2px 0;display:flex;gap:6px;}\n.bq-opt.cor{color:var(--gd);font-weight:700;}\n.bq-opt-lbl{font-size:11px;font-weight:700;width:16px;flex-shrink:0;}\n.banco-count{text-align:center;font-size:12px;color:var(--g500);padding:6px;}\n\n/* ── MODAL ── */\n.moverlay{display:none;position:fixed;inset:0;background:rgba(10,22,40,.8);\n  z-index:100;justify-content:center;align-items:center;backdrop-filter:blur(4px);}\n.moverlay.show{display:flex;}\n.modal{background:#fff;border-radius:16px;padding:28px 24px;max-width:480px;width:92%;\n  text-align:center;box-shadow:0 8px 32px rgba(0,0,0,.2);border-top:4px solid var(--gold);\n  max-height:88vh;overflow-y:auto;}\n.modal h2{font-family:\'Barlow Condensed\',sans-serif;font-size:20px;font-weight:700;\n  color:var(--navy);margin-bottom:14px;text-transform:uppercase;letter-spacing:1px;}\n.bscore{font-family:\'Barlow Condensed\',sans-serif;font-size:60px;font-weight:800;\n  margin:12px 0;line-height:1;}\n.bscore.pass{color:var(--green);} .bscore.fail{color:var(--red);}\n.modal p{font-size:13px;color:var(--g500);margin:4px 0;}\n.modal .btn{margin:7px 4px 0;}\n.topic-results{margin:10px 0;text-align:left;}\n.topic-row{display:flex;justify-content:space-between;align-items:center;\n  padding:6px 10px;border-radius:6px;margin-bottom:3px;font-size:12px;}\n\n/* ── RESPONSIVE ── */\n@media(max-width:480px){\n  .home-cards{grid-template-columns:1fr;}\n  .topic-grid{grid-template-columns:1fr;}\n  .htitle{font-size:15px;letter-spacing:1px;}\n  .hsub{display:none;}\n  .hbtn{font-size:10px;padding:4px 8px;}\n  .stat{padding:7px 10px;}\n  .sv{font-size:18px;}\n  .sl{font-size:8px;}\n  .rtxt{font-size:34px;}\n  .rico{font-size:66px;}\n  .sidebar{width:170px;}.sidebar.collapsed{margin-right:-170px;}\n  .toggle{right:170px;}.toggle.collapsed{right:0;}\n  .banco-filters{gap:4px;}\n  .bfilter{font-size:10px;padding:4px 9px;}\n}\n@media(min-width:769px){\n  .home-cards{grid-template-columns:1fr 1fr;}\n  .topic-grid{grid-template-columns:1fr 1fr;}\n  .qtext{font-size:16px;}\n  .otxt{font-size:15px;}\n}\n</style>\n</head>\n<body>\n\n<!-- HEADER -->\n<div class="hdr">\n  <div class="hbrand">\n    <span style="font-size:26px">&#x1F6E1;</span>\n    <div>\n      <div class="htitle">Evaluacion Integral Policial</div>\n      <div class="hsub">Mediacion &bull; Mandatorios &bull; Competencias &bull; Desarrollado por <strong>GHOST1D</strong></div>\n    </div>\n  </div>\n  <div class="hctrl">\n    <button class="hbtn" id="hbtnhome" onclick="goHome()">&#x1F3E0; Inicio</button>\n    <button class="hbtn" id="hbtnshuffle" onclick="shuffleQs()" style="display:none">&#x1F500;</button>\n    <button class="hbtn" id="hbtnreset"   onclick="resetAll()"  style="display:none">&#x21BB;</button>\n    <span class="hmenu" onclick="toggleSB()">&#x2630;</span>\n  </div>\n</div>\n\n<!-- STATS -->\n<div class="stats" id="statsbar" style="display:none">\n  <div class="stat"><div class="sv vq"><span id="scur">1</span>/<span id="stot">0</span></div><div class="sl">Pregunta</div></div>\n  <div class="stat"><div class="sv vok" id="sok">0</div><div class="sl">Aciertos</div></div>\n  <div class="stat"><div class="sv vfail" id="sfail">0</div><div class="sl">Fallos</div></div>\n  <div class="stat"><div class="sv vpts" id="spts">0</div><div class="sl">Puntos</div></div>\n</div>\n\n<!-- MAIN -->\n<div class="main">\n\n  <!-- HOME -->\n  <div class="homescreen" id="homescreen">\n    <div class="home-title">&#x1F6E1; Centro de Estudios Policial</div>\n    <div class="home-sub">554 preguntas &bull; Cursos mandatorios &bull; Selecciona el modo</div>\n\n    <div class="home-cards">\n      <div class="home-card featured" onclick="startMode(\'general\')">\n        <div class="hcard-icon">&#x1F4DA;</div>\n        <div class="hcard-title">Test General</div>\n        <div class="hcard-desc">Todas las preguntas aleatorias de todos los temas.</div>\n        <span class="hcard-badge">554 preguntas</span>\n      </div>\n      <div class="home-card" onclick="startMode(\'final\')">\n        <div class="hcard-icon">&#x1F3AF;</div>\n        <div class="hcard-title">Prueba Final</div>\n        <div class="hcard-desc">Simulacro: 36 preguntas, 9 por cada tema.</div>\n        <span class="hcard-badge" style="background:#c0392b">36 pregs &bull; 9/tema</span>\n      </div>\n    </div>\n\n    <div style="font-family:\'Barlow Condensed\',sans-serif;font-size:15px;font-weight:700;color:var(--navy);text-transform:uppercase;letter-spacing:.8px;">\n      &#x1F4AA; Refuerza un tema espec&#xED;fico\n    </div>\n    <div class="topic-grid">\n      <button class="tbtn" onclick="startTopicMode(\'Atencion al Ciudadano\')" style="border-color:#1565c0;color:#1565c0">\n        <span class="tbtn-icon">&#x1F91D;</span>\n        <span class="tbtn-name">Atencion al Ciudadano</span>\n        <span class="tbtn-count">111 pregs.</span>\n      </button>\n      <button class="tbtn" onclick="startTopicMode(\'Derechos Humanos\')" style="border-color:#6a1b9a;color:#6a1b9a">\n        <span class="tbtn-icon">&#x2696;&#xFE0F;</span>\n        <span class="tbtn-name">Derechos Humanos</span>\n        <span class="tbtn-count">60 pregs.</span>\n      </button>\n      <button class="tbtn" onclick="startTopicMode(\'Procedimientos Policiales\')" style="border-color:#00695c;color:#00695c">\n        <span class="tbtn-icon">&#x1F694;</span>\n        <span class="tbtn-name">Procedimientos Policiales</span>\n        <span class="tbtn-count">239 pregs.</span>\n      </button>\n      <button class="tbtn" onclick="startTopicMode(\'Uso de la Fuerza\')" style="border-color:#b71c1c;color:#b71c1c">\n        <span class="tbtn-icon">&#x1F6E1;&#xFE0F;</span>\n        <span class="tbtn-name">Uso de la Fuerza</span>\n        <span class="tbtn-count">144 pregs.</span>\n      </button>\n    </div>\n\n    <!-- BANCO button -->\n    <button class="banco-btn" onclick="showBanco()">\n      <span style="font-size:28px">&#x1F4D6;</span>\n      <div>\n        <div class="banco-btn-text">&#x1F50D; Banco de Preguntas</div>\n        <div class="banco-btn-sub">Busca cualquier pregunta con su respuesta correcta</div>\n      </div>\n    </button>\n  </div>\n\n  <!-- QUESTION WRAPPER -->\n  <div class="qwrap hidden" id="qwrap">\n    <div class="qmode-bar">\n      <span id="modelabel">Test</span>\n      <span style="opacity:.6;font-size:10px">Toca una opci&#xF3;n para responder</span>\n    </div>\n    <div class="progbar" id="progbar" style="display:none">\n      <div class="prog-lbl" id="proglbl"></div>\n      <div class="progbar-inner"><div class="progbar-fill" id="progfill" style="width:0%"></div></div>\n    </div>\n    <div class="qpanel" id="qpanel">\n      <div class="qcard" id="qcard">\n        <div class="qsrc" id="qsrc"></div>\n        <div class="qtext" id="qtext"></div>\n        <div class="qopts" id="qopts"></div>\n        <div class="roverlay" id="ro">\n          <div class="rico" id="rico"></div>\n          <div class="rtxt" id="rtxt"></div>\n          <div class="rsub" id="rsub"></div>\n        </div>\n        <div class="cbox" id="cbox"></div>\n      </div>\n    </div>\n  </div>\n\n  <!-- BANCO DE PREGUNTAS -->\n  <div class="banco hidden" id="banco">\n    <div class="banco-top">\n      <div style="display:flex;align-items:center;justify-content:space-between;">\n        <div class="banco-title">&#x1F4D6; Banco de Preguntas</div>\n        <button class="btn btnhome" style="font-size:12px;padding:6px 12px;" onclick="goHome()">&#x2190; Inicio</button>\n      </div>\n      <div class="banco-search">\n        <input class="search-inp" id="searchInp" type="text"\n          placeholder="&#x1F50D; Buscar pregunta o respuesta..."\n          oninput="filterBanco()" autocomplete="off" autocorrect="off" spellcheck="false">\n      </div>\n      <div class="banco-filters" id="bancoFilters">\n        <button class="bfilter active" data-topic="" onclick="setBFilter(this,\'\')">Todos</button>\n        <button class="bfilter" data-topic="Atencion al Ciudadano"\n          style="border-color:#1565c0;color:#1565c0" onclick="setBFilter(this,\'Atencion al Ciudadano\')">Atenci&#xF3;n</button>\n        <button class="bfilter" data-topic="Derechos Humanos"\n          style="border-color:#6a1b9a;color:#6a1b9a" onclick="setBFilter(this,\'Derechos Humanos\')">D. Humanos</button>\n        <button class="bfilter" data-topic="Procedimientos Policiales"\n          style="border-color:#00695c;color:#00695c" onclick="setBFilter(this,\'Procedimientos Policiales\')">Procedimientos</button>\n        <button class="bfilter" data-topic="Uso de la Fuerza"\n          style="border-color:#b71c1c;color:#b71c1c" onclick="setBFilter(this,\'Uso de la Fuerza\')">Uso Fuerza</button>\n      </div>\n    </div>\n    <div class="banco-count" id="bancoCount"></div>\n      <div class="dl-row">\n        <button class="dl-btn dl-btn-pdf" onclick="descargarPDF(true)">\n          <span class="dl-ico">&#x1F4CB;</span>\n          <span class="dl-lbl">Descargar PDF<small>Con respuestas</small></span>\n        </button>\n        <button class="dl-btn dl-btn-word" onclick="descargarWord(true)">\n          <span class="dl-ico">&#x1F4C4;</span>\n          <span class="dl-lbl">Descargar Word<small>Con respuestas</small></span>\n        </button>\n        <button class="dl-btn dl-btn-exam" onclick="descargarWord(false)">\n          <span class="dl-ico">&#x270D;</span>\n          <span class="dl-lbl">Para Imprimir<small>Sin respuestas</small></span>\n        </button>\n      </div>\n    <div class="banco-list" id="bancoList"></div>\n  </div>\n\n  <!-- SIDEBAR -->\n  <div class="toggle" id="tog" onclick="toggleSB()">&#x25C0;</div>\n  <div class="sidebar" id="sb">\n    <div class="sbhead">\n      <span>Cuestiones</span>\n      <span style="opacity:.6;font-size:11px;cursor:default">?</span>\n    </div>\n    <div class="sbbody" id="sblist"></div>\n  </div>\n</div>\n\n<!-- BOTTOM NAV -->\n<div class="bottom" id="bottombar" style="display:none">\n  <button class="btn btnhome" onclick="goHome()" title="Inicio">&#x1F3E0;</button>\n  <button class="btn btnnav"  onclick="prevQ()">&#x25C0;</button>\n  <button class="btn btnnav"  onclick="nextQ()">&#x25B6;</button>\n  <button class="btn btnres"  onclick="showResults()">&#x1F4CA; Resultados</button>\n</div>\n\n<!-- RESULTS MODAL -->\n<div class="moverlay" id="mov">\n  <div class="modal">\n    <h2 id="rtitle">Resultados</h2>\n    <div class="bscore" id="rscore">0%</div>\n    <p id="rdet"></p>\n    <div class="topic-results" id="rtopics"></div>\n    <br>\n    <button class="btn" onclick="closeR()">Cerrar</button>\n    <button class="btn" style="background:#fce4e1;border-color:#c0392b;color:#922b21"\n      onclick="closeR();resetAll()">Reiniciar</button>\n    <button class="btn" style="background:#e8f4fd;border-color:#1565c0;color:#1565c0"\n      onclick="closeR();goHome()">Inicio</button>\n  </div>\n</div>\n\n<script>\n'

HTML_SUFFIX = '\n\nconst TOPICS=["Atencion al Ciudadano","Derechos Humanos","Procedimientos Policiales","Uso de la Fuerza"];\nconst TOPIC_COLORS={"Atencion al Ciudadano":"#1565c0","Derechos Humanos":"#6a1b9a","Procedimientos Policiales":"#00695c","Uso de la Fuerza":"#b71c1c"};\nconst TOPIC_ICONS={"Atencion al Ciudadano":"[AC]","Derechos Humanos":"[DH]","Procedimientos Policiales":"[PP]","Uso de la Fuerza":"[UF]"};\nconst TOPIC_COUNTS={"Atencion al Ciudadano":111,"Derechos Humanos":60,"Procedimientos Policiales":239,"Uso de la Fuerza":144};\n\nlet sdCache={},fIdx=[],pos=0,ans={},okN=0,failN=0,currentMode=\'\';\nlet bTopicFilter=\'\',bSearchTerm=\'\';\n\nfunction shuffle(a){\n  const r=[...a];\n  for(let i=r.length-1;i>0;i--){\n    const j=Math.floor(Math.random()*(i+1));[r[i],r[j]]=[r[j],r[i]];\n  }\n  return r;\n}\nfunction prepQ(qi){\n  if(sdCache[qi])return;\n  const q=QS[qi];\n  const ord=shuffle(q.opts.map((_,i)=>i));\n  sdCache[qi]={ord,ci:ord.indexOf(q.c)};\n}\n\n// ── HOME ──\nfunction goHome(){\n  document.getElementById(\'homescreen\').classList.remove(\'hidden\');\n  document.getElementById(\'qwrap\').classList.add(\'hidden\');\n  document.getElementById(\'banco\').classList.add(\'hidden\');\n  document.getElementById(\'statsbar\').style.display=\'none\';\n  document.getElementById(\'bottombar\').style.display=\'none\';\n  document.getElementById(\'hbtnshuffle\').style.display=\'none\';\n  document.getElementById(\'hbtnreset\').style.display=\'none\';\n  document.getElementById(\'mov\').classList.remove(\'show\');\n}\n\n// ── BANCO ──\nfunction showBanco(){\n  document.getElementById(\'homescreen\').classList.add(\'hidden\');\n  document.getElementById(\'qwrap\').classList.add(\'hidden\');\n  document.getElementById(\'banco\').classList.remove(\'hidden\');\n  document.getElementById(\'statsbar\').style.display=\'none\';\n  document.getElementById(\'bottombar\').style.display=\'none\';\n  bTopicFilter=\'\'; bSearchTerm=\'\';\n  document.getElementById(\'searchInp\').value=\'\';\n  renderBanco();\n}\n\nfunction renderBanco(){\n  const list=document.getElementById(\'bancoList\');\n  const term=bSearchTerm.toLowerCase().trim();\n  let items=QS.map((q,i)=>{return{...q,_i:i};});\n  if(bTopicFilter) items=items.filter(q=>q.tp===bTopicFilter);\n  if(term) items=items.filter(q=>\n    q.q.toLowerCase().includes(term)||\n    q.opts.some(o=>o.toLowerCase().includes(term))\n  );\n  document.getElementById(\'bancoCount\').textContent=items.length+\' preguntas encontradas\';\n  const labels=[\'A\',\'B\',\'C\',\'D\'];\n  list.innerHTML=items.map((q,n)=>{\n    const col=TOPIC_COLORS[q.tp]||\'#555\';\n    const corr=q.opts[q.c]||\'\';\n    const optsHtml=q.opts.map((o,i)=>{\n      const isCor=i===q.c;\n      return `<div class="bq-opt${isCor?\' cor\':\'\'}">\n        <span class="bq-opt-lbl">${labels[i]||i+1}.</span>\n        <span>${o}</span>\n      </div>`;\n    }).join(\'\');\n    return `<div class="bq" style="border-left-color:${col}">\n      <div class="bq-num">#${n+1}\n        <span class="bq-topic" style="background:${col}">${q.tp}</span>\n      </div>\n      <div class="bq-text">${q.q}</div>\n      <div class="bq-opts">${optsHtml}</div>\n      <div class="bq-answer correct">\n        <span class="bq-chk">&#x2713;</span>\n        <span><strong>Respuesta correcta:</strong> ${corr}</span>\n      </div>\n    </div>`;\n  }).join(\'\');\n  if(items.length===0)list.innerHTML=\'<div style="text-align:center;padding:40px;color:var(--g500);font-size:14px;">No se encontraron preguntas</div>\';\n}\n\nfunction filterBanco(){\n  bSearchTerm=document.getElementById(\'searchInp\').value;\n  renderBanco();\n}\n\n// ── DESCARGAS ──\nfunction getFilteredItems(){\n  const term=bSearchTerm.toLowerCase().trim();\n  let items=QS.map((q,i)=>{return{...q,_i:i};});\n  if(bTopicFilter) items=items.filter(q=>q.tp===bTopicFilter);\n  if(term) items=items.filter(q=>\n    q.q.toLowerCase().includes(term)||\n    q.opts.some(o=>o.toLowerCase().includes(term))\n  );\n  return items;\n}\n\nfunction descargarWord(conRespuestas){\n  const items=getFilteredItems();\n  const labels=[\'A\',\'B\',\'C\',\'D\'];\n  const topicLabel=bTopicFilter||\'Todos los temas\';\n  const titulo=conRespuestas\n    ?\'EVALUACION INTEGRAL - CURSOS MANDATORIOS (CON RESPUESTAS)\'\n    :\'EVALUACION INTEGRAL - CURSOS MANDATORIOS (SIN RESPUESTAS - PARA IMPRIMIR)\';\n\n  let html=`\n    <html xmlns:o="urn:schemas-microsoft-com:office:office"\n          xmlns:w="urn:schemas-microsoft-com:office:word"\n          xmlns="http://www.w3.org/TR/REC-html40">\n    <head><meta charset="utf-8">\n    <style>\n      body{font-family:Arial,sans-serif;font-size:11pt;margin:2cm;}\n      h1{font-size:16pt;color:#0a1628;text-align:center;border-bottom:2px solid #0a1628;padding-bottom:6pt;}\n      h2{font-size:11pt;color:#0a1628;margin-top:2pt;text-align:center;font-weight:normal;}\n      .meta{text-align:center;font-size:9pt;color:#555;margin-bottom:16pt;}\n      .pregunta{margin-bottom:16pt;page-break-inside:avoid;border-left:3px solid #0a1628;padding-left:10pt;}\n      .num{font-size:8pt;font-weight:bold;color:#666;text-transform:uppercase;letter-spacing:.5pt;}\n      .tema{display:inline-block;background:#0a1628;color:#fff;font-size:7pt;font-weight:bold;\n             padding:1pt 5pt;border-radius:3pt;margin-left:4pt;}\n      .texto{font-size:11pt;font-weight:bold;margin:4pt 0 8pt;line-height:1.4;}\n      .opciones{margin-left:8pt;}\n      .opcion{font-size:10.5pt;padding:2pt 0;line-height:1.3;}\n      .opcion.correcta{color:#2e7d32;font-weight:bold;}\n      .respuesta{margin-top:6pt;padding:4pt 8pt;background:#e8f5e9;border-radius:3pt;\n                  font-size:10pt;color:#1b5e20;border:1pt solid #a5d6a7;}\n      .espacio{height:28pt;border-bottom:1pt solid #ccc;margin:8pt 0;\n               font-size:9pt;color:#aaa;} \n    </style>\n    </head><body>\n    <h1>&#x1F46E; ${titulo}</h1>\n    <h2>Policia Nacional de Colombia &mdash; Cursos Mandatorios</h2>\n    <div class="meta">Tema: ${topicLabel} &nbsp;|&nbsp; ${items.length} preguntas &nbsp;|&nbsp; Generado: ${new Date().toLocaleDateString(\'es-CO\')}</div>\n  `;\n\n  items.forEach((q,n)=>{\n    const topicColor={\'Atencion al Ciudadano\':\'#1565c0\',\'Derechos Humanos\':\'#6a1b9a\',\n      \'Procedimientos Policiales\':\'#00695c\',\'Uso de la Fuerza\':\'#b71c1c\'}[q.tp]||\'#0a1628\';\n    html+=`<div class="pregunta" style="border-left-color:${topicColor}">`;\n    html+=`<div class="num">#${n+1} <span class="tema" style="background:${topicColor}">${q.tp}</span></div>`;\n    html+=`<div class="texto">${q.q}</div>`;\n    html+=`<div class="opciones">`;\n    q.opts.forEach((o,i)=>{\n      if(conRespuestas){\n        const esCor=i===q.c;\n        html+=`<div class="opcion${esCor?\' correcta\':\'\'}">${labels[i]||String.fromCharCode(65+i)}. ${o}${esCor?\' &#x2713;\':\'\'}</div>`;\n      } else {\n        html+=`<div class="opcion">${labels[i]||String.fromCharCode(65+i)}. ${o}</div>`;\n      }\n    });\n    html+=`</div>`;\n    if(conRespuestas){\n      html+=`<div class="respuesta">&#x2714; <strong>Respuesta correcta:</strong> ${q.opts[q.c]}</div>`;\n    } else {\n      html+=`<div class="espacio">Respuesta: _______________________________________________</div>`;\n    }\n    html+=`</div>`;\n  });\n  html+=\'</body></html>\';\n\n  const blob=new Blob([\'\ufeff\'+html],{type:\'application/msword\'});\n  const url=URL.createObjectURL(blob);\n  const a=document.createElement(\'a\');\n  a.href=url;\n  a.download=conRespuestas\n    ?`Banco_Preguntas_CON_respuestas_${topicLabel.replace(/\\s+/g,\'_\')}.doc`\n    :`Banco_Preguntas_SIN_respuestas_${topicLabel.replace(/\\s+/g,\'_\')}.doc`;\n  a.click();\n  setTimeout(()=>URL.revokeObjectURL(url),2000);\n}\n\nfunction descargarPDF(conRespuestas){\n  const items=getFilteredItems();\n  const labels=[\'A\',\'B\',\'C\',\'D\'];\n  const topicLabel=bTopicFilter||\'Todos los temas\';\n  const titulo=conRespuestas\n    ?\'EVALUACION INTEGRAL - CURSOS MANDATORIOS\'\n    :\'EVALUACION INTEGRAL - PARA IMPRIMIR (SIN RESPUESTAS)\';\n\n  const topicColors={\'Atencion al Ciudadano\':\'#1565c0\',\'Derechos Humanos\':\'#6a1b9a\',\n    \'Procedimientos Policiales\':\'#00695c\',\'Uso de la Fuerza\':\'#b71c1c\'};\n\n  let body=\'\';\n  items.forEach((q,n)=>{\n    const col=topicColors[q.tp]||\'#0a1628\';\n    body+=`<div style="margin-bottom:18px;padding:12px 14px;border-left:4px solid ${col};\n      background:#fff;border-radius:0 8px 8px 0;page-break-inside:avoid;">\n      <div style="font-size:9px;font-weight:700;color:#777;text-transform:uppercase;margin-bottom:4px;">\n        #${n+1}&nbsp;<span style="background:${col};color:#fff;padding:1px 6px;border-radius:3px;font-size:8px;">${q.tp}</span>\n      </div>\n      <div style="font-size:12px;font-weight:600;color:#111;margin-bottom:8px;line-height:1.45;">${q.q}</div>\n      <div style="margin-left:6px;">`;\n    q.opts.forEach((o,i)=>{\n      if(conRespuestas){\n        const esCor=i===q.c;\n        body+=`<div style="font-size:11px;padding:2px 0;color:${esCor?\'#2e7d32\':\'#444\'};font-weight:${esCor?\'700\':\'400\'};">\n          ${labels[i]}. ${o}${esCor?\' &#x2714;\':\'\'}</div>`;\n      } else {\n        body+=`<div style="font-size:11px;padding:4px 0;color:#333;border-bottom:1px solid #eee;">\n          ${labels[i]}. ${o}</div>`;\n      }\n    });\n    body+=\'</div>\';\n    if(conRespuestas){\n      body+=`<div style="margin-top:7px;padding:5px 10px;background:#e8f5e9;border-radius:4px;\n        font-size:10px;color:#1b5e20;font-weight:600;">&#x2714; Respuesta: ${q.opts[q.c]}</div>`;\n    } else {\n      body+=`<div style="margin-top:8px;border-top:1px dashed #ccc;padding-top:4px;\n        font-size:9px;color:#bbb;">Mi respuesta: _______________________</div>`;\n    }\n    body+=\'</div>\';\n  });\n\n  const printWin=window.open(\'\',\'_blank\',\'width=900,height=700\');\n  printWin.document.write(`<!DOCTYPE html><html><head><meta charset="utf-8">\n    <title>${titulo}</title>\n    <style>\n      *{box-sizing:border-box;margin:0;padding:0;}\n      body{font-family:Arial,sans-serif;background:#f4f4f4;padding:20px;}\n      .header{text-align:center;padding:16px;background:#0a1628;color:#fff;border-radius:10px;margin-bottom:20px;}\n      .header h1{font-size:15px;text-transform:uppercase;letter-spacing:1px;}\n      .header p{font-size:11px;opacity:.8;margin-top:4px;}\n      .content{max-width:800px;margin:0 auto;}\n      @media print{\n        body{background:#fff;padding:0;}\n        .no-print{display:none;}\n        .header{border-radius:0;}\n      }\n    </style>\n  </head><body>\n    <div class="header">\n      <h1>&#x1F46E; ${titulo}</h1>\n      <p>Policia Nacional de Colombia &mdash; Cursos Mandatorios &mdash; ${topicLabel} &mdash; ${items.length} preguntas</p>\n    </div>\n    <div style="text-align:center;margin-bottom:16px;" class="no-print">\n      <button onclick="window.print()" style="background:#c62828;color:#fff;border:none;padding:10px 24px;\n        border-radius:8px;font-size:14px;font-weight:700;cursor:pointer;margin-right:8px;">\n        &#x1F5A8; Imprimir / Guardar PDF\n      </button>\n      <button onclick="window.close()" style="background:#555;color:#fff;border:none;padding:10px 18px;\n        border-radius:8px;font-size:14px;cursor:pointer;">Cerrar</button>\n    </div>\n    <div class="content">${body}</div>\n  </body></html>`);\n  printWin.document.close();\n  setTimeout(()=>printWin.focus(),300);\n}\n\nfunction setBFilter(el,topic){\n  bTopicFilter=topic;\n  document.querySelectorAll(\'.bfilter\').forEach(b=>{\n    b.classList.remove(\'active\');\n    b.style.background=\'\';\n    b.style.color=b.dataset.topic?TOPIC_COLORS[b.dataset.topic]||\'\':\'var(--navy)\';\n    b.style.borderColor=b.dataset.topic?TOPIC_COLORS[b.dataset.topic]||\'var(--g200)\':\'var(--g200)\';\n  });\n  el.classList.add(\'active\');\n  const col=topic?TOPIC_COLORS[topic]:\'var(--navy)\';\n  el.style.background=col; el.style.color=\'#fff\'; el.style.borderColor=col;\n  renderBanco();\n}\n\n// ── START MODES ──\nfunction startMode(mode){\n  currentMode=mode;ans={};okN=0;failN=0;sdCache={};\n  if(mode===\'general\'){\n    fIdx=shuffle(QS.map((_,i)=>i));\n    document.getElementById(\'modelabel\').textContent=\'&#x1F4DA; Test General (\'+fIdx.length+\')\';\n    document.getElementById(\'progbar\').style.display=\'none\';\n    document.getElementById(\'hbtnshuffle\').style.display=\'\';\n  }else if(mode===\'final\'){\n    fIdx=[];\n    TOPICS.forEach(t=>{\n      const pool=shuffle(QS.map((_,i)=>i).filter(i=>QS[i].tp===t));\n      fIdx.push(...pool.slice(0,9));\n    });\n    fIdx=shuffle(fIdx);\n    document.getElementById(\'modelabel\').textContent=\'&#x1F3AF; Prueba Final (36)\';\n    document.getElementById(\'progbar\').style.display=\'block\';\n    document.getElementById(\'hbtnshuffle\').style.display=\'none\';\n  }\n  updateStats();buildSB();showQView();showQ(0);\n}\n\nfunction startTopicMode(topic){\n  currentMode=topic;ans={};okN=0;failN=0;sdCache={};\n  const pool=shuffle(QS.map((_,i)=>i).filter(i=>QS[i].tp===topic));\n  fIdx=pool.slice(0,36);\n  document.getElementById(\'modelabel\').textContent=TOPIC_ICONS[topic]+\' \'+topic+\' (36)\';\n  document.getElementById(\'progbar\').style.display=\'block\';\n  document.getElementById(\'hbtnshuffle\').style.display=\'none\';\n  updateStats();buildSB();showQView();showQ(0);\n}\n\nfunction showQView(){\n  document.getElementById(\'homescreen\').classList.add(\'hidden\');\n  document.getElementById(\'banco\').classList.add(\'hidden\');\n  document.getElementById(\'qwrap\').classList.remove(\'hidden\');\n  document.getElementById(\'statsbar\').style.display=\'flex\';\n  document.getElementById(\'bottombar\').style.display=\'flex\';\n  document.getElementById(\'hbtnreset\').style.display=\'\';\n}\n\n// ── SHOW QUESTION ──\nfunction showQ(p){\n  if(p<0||p>=fIdx.length)return;\n  pos=p;\n  const qi=fIdx[p],q=QS[qi];\n  prepQ(qi);\n  const sd=sdCache[qi],st=ans[qi];\n  const col=TOPIC_COLORS[q.tp]||\'#0a1628\';\n  document.getElementById(\'qsrc\').innerHTML=\n    \'&#x1F4CB; \'+q.src+\n    \'<span class="qtbadge" style="background:\'+col+\'">\'+\n    (TOPIC_ICONS[q.tp]||\'\')+\'&nbsp;\'+q.tp+\'</span>\';\n  document.getElementById(\'qtext\').textContent=q.q;\n  document.getElementById(\'ro\').className=\'roverlay\';\n  document.getElementById(\'cbox\').innerHTML=\'\';\n  const od=document.getElementById(\'qopts\');\n  od.innerHTML=\'\';\n  sd.ord.forEach((origIdx,di)=>{\n    const d=document.createElement(\'div\');\n    let cls=\'opt\';\n    if(st){\n      const sel=ans[qi+\'_s\'];\n      if(di===sd.ci) cls=(di===sel&&st===\'ok\')?\'opt correct answered\':\'opt wascorrect answered\';\n      else if(di===sel&&st===\'fail\') cls=\'opt incorrect answered\';\n      else cls=\'opt answered\';\n    }\n    d.className=cls;\n    d.innerHTML=\'<div class="ocirc"></div><div class="otxt">\'+q.opts[origIdx]+\'</div>\';\n    if(!st) d.onclick=()=>pick(qi,di,sd);\n    od.appendChild(d);\n  });\n  document.getElementById(\'scur\').textContent=p+1;\n  document.getElementById(\'stot\').textContent=fIdx.length;\n  if(document.getElementById(\'progbar\').style.display!==\'none\'){\n    const done=Object.keys(ans).filter(k=>!k.endsWith(\'_s\')).length;\n    const pct=Math.round(done/fIdx.length*100);\n    document.getElementById(\'progfill\').style.width=pct+\'%\';\n    document.getElementById(\'proglbl\').textContent=done+\'/\'+fIdx.length+\' respondidas (\'+pct+\'%)\';\n  }\n  document.querySelectorAll(\'.sbi\').forEach((el,i)=>el.classList.toggle(\'active\',i===p));\n  const ae=document.querySelector(\'.sbi.active\');\n  if(ae)ae.scrollIntoView({block:\'nearest\'});\n  document.getElementById(\'qpanel\').scrollTop=0;\n}\n\n// ── PICK = AUTO CORRECTION ──\nfunction pick(qi,di,sd){\n  if(ans[qi])return;\n  ans[qi+\'_s\']=di;\n  const ok=(di===sd.ci);\n  if(ok){ans[qi]=\'ok\';okN++;}else{ans[qi]=\'fail\';failN++;}\n  updateStats();\n  const opts=document.querySelectorAll(\'.opt\');\n  sd.ord.forEach((origIdx,oi)=>{\n    opts[oi].onclick=null;\n    opts[oi].classList.add(\'answered\');\n    if(oi===sd.ci) opts[oi].className=(ok&&oi===di)?\'opt correct answered\':\'opt wascorrect answered\';\n    if(oi===di&&!ok) opts[oi].className=\'opt incorrect answered\';\n  });\n  const ro=document.getElementById(\'ro\');\n  if(ok){\n    ro.className=\'roverlay show rcorrect\';\n    document.getElementById(\'rico\').innerHTML=\'&#x1F389;\';\n    document.getElementById(\'rtxt\').className=\'rtxt rg\';\n    document.getElementById(\'rtxt\').textContent=\'\\xA1CORRECTO!\';\n    document.getElementById(\'rsub\').textContent=\'+1 Punto\';\n    spawnConfetti();\n  }else{\n    ro.className=\'roverlay show rincorrect\';\n    document.getElementById(\'rico\').innerHTML=\'&#x274C;\';\n    document.getElementById(\'rtxt\').className=\'rtxt rr\';\n    document.getElementById(\'rtxt\').textContent=\'INCORRECTO\';\n    document.getElementById(\'rsub\').textContent=\'Revisa el tema\';\n  }\n  updSBI(pos);\n  setTimeout(()=>{\n    ro.className=\'roverlay\';\n    document.getElementById(\'cbox\').innerHTML=\'\';\n    if(pos<fIdx.length-1)showQ(pos+1);\n    else setTimeout(showResults,500);\n  },1800);\n}\n\nfunction spawnConfetti(){\n  const box=document.getElementById(\'cbox\');\n  box.innerHTML=\'\';\n  const cols=[\'#39ff14\',\'#00e676\',\'#ffeb3b\',\'#00bcd4\',\'#e040fb\',\'#ff9800\',\'#76ff03\',\'#ffffff\'];\n  for(let i=0;i<55;i++){\n    const c=document.createElement(\'div\');\n    c.className=\'conf\';\n    c.style.left=Math.random()*100+\'%\';\n    c.style.backgroundColor=cols[Math.floor(Math.random()*cols.length)];\n    c.style.animationDelay=Math.random()*.9+\'s\';\n    c.style.animationDuration=(1.4+Math.random()*.8)+\'s\';\n    c.style.width=(5+Math.random()*9)+\'px\';\n    c.style.height=(5+Math.random()*9)+\'px\';\n    c.style.borderRadius=Math.random()>.5?\'50%\':\'2px\';\n    box.appendChild(c);\n  }\n}\n\nfunction nextQ(){if(pos<fIdx.length-1)showQ(pos+1);}\nfunction prevQ(){if(pos>0)showQ(pos-1);}\n\nfunction updateStats(){\n  document.getElementById(\'sok\').textContent=okN;\n  document.getElementById(\'sfail\').textContent=failN;\n  document.getElementById(\'spts\').textContent=okN;\n}\n\nfunction buildSB(){\n  const l=document.getElementById(\'sblist\');\n  l.innerHTML=\'\';\n  fIdx.forEach((qi,p)=>{\n    const d=document.createElement(\'div\');\n    const st=ans[qi];\n    d.className=\'sbi\'+(p===0?\' active\':\'\')+(st===\'ok\'?\' ok\':st===\'fail\'?\' fail\':\'\');\n    d.id=\'sb\'+p;\n    d.innerHTML=\'<span>Preg. \'+(p+1)+\'</span><span class="sbico">\'+(st===\'ok\'?\'\\u2713\':st===\'fail\'?\'\\u2717\':\'\')+\'</span>\';\n    d.onclick=()=>showQ(p);\n    l.appendChild(d);\n  });\n}\n\nfunction updSBI(p){\n  const qi=fIdx[p],d=document.getElementById(\'sb\'+p);\n  if(!d)return;\n  const st=ans[qi];\n  d.className=\'sbi\'+(p===pos?\' active\':\'\')+(st===\'ok\'?\' ok\':st===\'fail\'?\' fail\':\'\');\n  d.querySelector(\'.sbico\').textContent=st===\'ok\'?\'\\u2713\':st===\'fail\'?\'\\u2717\':\'\';\n}\n\nfunction toggleSB(){\n  const s=document.getElementById(\'sb\'),t=document.getElementById(\'tog\');\n  s.classList.toggle(\'collapsed\');t.classList.toggle(\'collapsed\');\n  t.innerHTML=s.classList.contains(\'collapsed\')?\'&#x25B6;\':\'&#x25C0;\';\n}\n\nfunction shuffleQs(){\n  if(currentMode!==\'general\')return;\n  fIdx=shuffle(QS.map((_,i)=>i));\n  sdCache={};buildSB();showQ(0);\n}\n\nfunction resetAll(){\n  ans={};okN=0;failN=0;sdCache={};\n  updateStats();\n  document.getElementById(\'mov\').classList.remove(\'show\');\n  startMode(currentMode);\n}\n\nfunction showResults(){\n  const tot=fIdx.length,resp=okN+failN;\n  const pct=resp>0?Math.round(okN/resp*100):0;\n  const sc=document.getElementById(\'rscore\');\n  sc.textContent=pct+\'%\';\n  sc.className=\'bscore \'+(pct>=60?\'pass\':\'fail\');\n  document.getElementById(\'rtitle\').textContent=\n    currentMode===\'final\'?\'Resultados Prueba Final\':\n    currentMode===\'general\'?\'Resultados Test General\':\'Resultados: \'+currentMode;\n  document.getElementById(\'rdet\').textContent=\n    \'Respondidas: \'+resp+\'/\'+tot+\' | Aciertos: \'+okN+\' | Fallos: \'+failN;\n  const tRes={};\n  TOPICS.forEach(t=>{tRes[t]={ok:0,fail:0,total:0};});\n  fIdx.forEach(qi=>{\n    const q=QS[qi],t=q.tp;\n    if(!tRes[t])tRes[t]={ok:0,fail:0,total:0};\n    tRes[t].total++;\n    if(ans[qi]===\'ok\')tRes[t].ok++;\n    else if(ans[qi]===\'fail\')tRes[t].fail++;\n  });\n  let tHtml=\'\';\n  Object.entries(tRes).forEach(([t,r])=>{\n    if(!r.total)return;\n    const pct2=r.ok+r.fail>0?Math.round(r.ok/(r.ok+r.fail)*100):0;\n    const col=TOPIC_COLORS[t]||\'#555\';\n    tHtml+=`<div class="topic-row" style="background:${col}18">\n      <span style="color:${col};font-weight:600">${TOPIC_ICONS[t]} ${t}</span>\n      <span style="color:${col};font-weight:700">${r.ok}/${r.total} (${pct2}%)</span>\n    </div>`;\n  });\n  document.getElementById(\'rtopics\').innerHTML=tHtml;\n  document.getElementById(\'mov\').classList.add(\'show\');\n}\nfunction closeR(){document.getElementById(\'mov\').classList.remove(\'show\');}\n\n// Keyboard shortcuts (desktop)\ndocument.addEventListener(\'keydown\',e=>{\n  const inQ=!document.getElementById(\'qwrap\').classList.contains(\'hidden\');\n  if(!inQ)return;\n  if(e.key===\'ArrowRight\'||e.key===\'ArrowDown\'){e.preventDefault();nextQ();}\n  else if(e.key===\'ArrowLeft\'||e.key===\'ArrowUp\'){e.preventDefault();prevQ();}\n  else if(e.key>=\'1\'&&e.key<=\'4\'){\n    const oi=parseInt(e.key)-1;\n    const qi=fIdx[pos];\n    if(!ans[qi]&&sdCache[qi]&&oi<QS[qi].opts.length)pick(qi,oi,sdCache[qi]);\n  }\n});\n\n// Init filter btn styles\ndocument.querySelectorAll(\'.bfilter\').forEach(b=>{\n  if(b.dataset.topic){\n    b.style.borderColor=TOPIC_COLORS[b.dataset.topic]||\'var(--g200)\';\n    b.style.color=TOPIC_COLORS[b.dataset.topic]||\'var(--navy)\';\n  }\n});\n\ngoHome();\n</script>\n</body>\n</html>'

html_content = HTML_PREFIX + js_data + HTML_SUFFIX
html_clean = html_content.encode('utf-8', errors='surrogatepass').decode('utf-8', errors='replace')

for filename in ('index.html', 'test_mediacion_policial.html'):
    out_path = os.path.join(BASE_DIR, filename)
    with open(out_path, 'w', encoding='utf-8') as f:
        f.write(html_clean)
    print(f"OK - Archivo actualizado: {out_path}")

c = Counter(len(q['opts']) for q in questions)
for n, cnt in sorted(c.items()):
    print(f"  {n} opciones: {cnt} preguntas")
